def bench(shape, BM, BN, nw, iters=50):
    x = torch.randn(shape, device="cuda") * 10
    for _ in range(5): run_cfg(x, BM, BN, nw)
    torch.cuda.synchronize()
    st=torch.cuda.Event(True); en=torch.cuda.Event(True); st.record()
    for _ in range(iters): run_cfg(x, BM, BN, nw)
    en.record(); torch.cuda.synchronize()
    gb = x.numel()*4*2/1e9
    return st.elapsed_time(en)/iters, gb/(st.elapsed_time(en)/iters/1e3)

